insert into quality_rule (id, tenant_id, project_id, deleted, created_at, updated_at, created_by, rule_name, rule_code, scope_type, rule_dimension, description, supported_datasource_types_json, granularity, logic_sql, enabled) values
(2047489216539025461, 'default', null, 0, '2026-04-24 09:34:04', '2026-04-24 09:34:04', 2047489207831650305, '表行数统计', 'DQ_TABLE_ROW_COUNT', 'SYSTEM', 'COMPLETENESS', '统计目标表总行数，常用于表级完整性、波动和空表监控。', '[]', 'TABLE', 'select count(*) as row_count from ${Schema_Table}', 1),
(2047489216539025464, 'default', null, 0, '2026-04-24 09:34:04', '2026-04-24 09:34:04', 2047489207831650305, '字段空值数统计', 'DQ_COLUMN_NULL_COUNT', 'SYSTEM', 'COMPLETENESS', '统计字段为空的记录数，适用于必填字段完整性校验。', '[]', 'COLUMN', 'select count(*) as null_count from ${Schema_Table} where ${Column} is null', 1),
(2047489216539025468, 'default', null, 0, '2026-04-24 09:34:04', '2026-04-24 09:34:04', 2047489207831650305, '字段填充率统计', 'DQ_COLUMN_FILL_RATE', 'SYSTEM', 'COMPLETENESS', '统计字段非空占比，适用于字段填充完整性趋势监控。', '[]', 'COLUMN', 'select case when count(*) = 0 then 0 else sum(case when ${Column} is not null then 1 else 0 end) * 1.0 / count(*) end as fill_rate from ${Schema_Table}', 1),
(2047489216539025472, 'default', null, 0, '2026-04-24 09:34:04', '2026-04-24 09:34:04', 2047489207831650305, '字符串空白值统计', 'DQ_STRING_BLANK_COUNT', 'SYSTEM', 'COMPLETENESS', '统计字段为空或空白字符串的记录数，适用于文本类必填字段校验。', '[]', 'COLUMN', 'select count(*) as blank_count from ${Schema_Table} where ${Column} is null or trim(${Column}) = ''''', 1),
(2047489216539025476, 'default', null, 0, '2026-04-24 09:34:04', '2026-04-24 09:34:04', 2047489207831650305, '字段去重值数量统计', 'DQ_COLUMN_DISTINCT_COUNT', 'SYSTEM', 'UNIQUENESS', '统计字段去重后的取值数量，适用于唯一性和基数监控。', '[]', 'COLUMN', 'select count(distinct ${Column}) as distinct_count from ${Schema_Table}', 1),
(2047489216539025480, 'default', null, 0, '2026-04-24 09:34:04', '2026-04-24 09:34:04', 2047489207831650305, '字段重复分组数统计', 'DQ_COLUMN_DUPLICATE_GROUP_COUNT', 'SYSTEM', 'UNIQUENESS', '统计字段值重复的分组数量，适用于主键、业务键唯一性校验。', '[]', 'COLUMN', 'select count(*) as duplicate_group_count from (select ${Column} from ${Schema_Table} group by ${Column} having count(*) > 1) dq', 1),
(2047489216539025484, 'default', null, 0, '2026-04-24 09:34:04', '2026-04-24 09:34:04', 2047489207831650305, '组合键重复分组数统计', 'DQ_COMPOSITE_KEY_DUPLICATE_GROUP_COUNT', 'SYSTEM', 'UNIQUENESS', '统计组合键重复的分组数量，适用于多字段业务主键唯一性校验。', '[]', 'TABLE', 'select count(*) as duplicate_group_count from (select ${KeyColumns} from ${Schema_Table} group by ${KeyColumns} having count(*) > 1) dq', 1),
(2047489216606134274, 'default', null, 0, '2026-04-24 09:34:04', '2026-04-24 09:34:04', 2047489207831650305, '数值范围异常数统计', 'DQ_NUMERIC_RANGE_INVALID_COUNT', 'SYSTEM', 'VALIDITY', '统计数值字段不在指定上下限范围内的记录数。', '[]', 'COLUMN', 'select count(*) as invalid_count from ${Schema_Table} where ${Column} is not null and (${Column} < ${MinValue} or ${Column} > ${MaxValue})', 1),
(2047489216606134280, 'default', null, 0, '2026-04-24 09:34:04', '2026-04-24 09:34:04', 2047489207831650305, '枚举值异常数统计', 'DQ_ENUM_INVALID_COUNT', 'SYSTEM', 'VALIDITY', '统计字段值不在允许枚举集合内的记录数。', '[]', 'COLUMN', 'select count(*) as invalid_count from ${Schema_Table} where ${Column} is not null and ${Column} not in (${AllowedValues})', 1),
(2047489216606134285, 'default', null, 0, '2026-04-24 09:34:04', '2026-04-24 09:34:04', 2047489207831650305, '字符串长度异常数统计', 'DQ_STRING_LENGTH_INVALID_COUNT', 'SYSTEM', 'VALIDITY', '统计字符串长度低于最小值或高于最大值的记录数。', '[]', 'COLUMN', 'select count(*) as invalid_count from ${Schema_Table} where ${Column} is not null and (length(${Column}) < ${MinLength} or length(${Column}) > ${MaxLength})', 1),
(2047489216606134291, 'default', null, 0, '2026-04-24 09:34:04', '2026-04-24 09:34:04', 2047489207831650305, 'LIKE 格式异常数统计', 'DQ_LIKE_PATTERN_INVALID_COUNT', 'SYSTEM', 'VALIDITY', '统计字段值不匹配指定 LIKE 模式的记录数。', '[]', 'COLUMN', 'select count(*) as invalid_count from ${Schema_Table} where ${Column} is not null and ${Column} not like ${LikePattern}', 1),
(2047489216606134296, 'default', null, 0, '2026-04-24 09:34:04', '2026-04-24 09:34:04', 2047489207831650305, '时间新鲜度过期数统计', 'DQ_STALE_TIME_COUNT', 'SYSTEM', 'TIMELINESS', '统计时间字段为空或早于新鲜度阈值的记录数。', '[]', 'COLUMN', 'select count(*) as stale_count from ${Schema_Table} where ${Column} is null or ${Column} < ${FreshnessThreshold}', 1),
(2047489216606134301, 'default', null, 0, '2026-04-24 09:34:04', '2026-04-24 09:34:04', 2047489207831650305, '未来时间值数量统计', 'DQ_FUTURE_TIME_COUNT', 'SYSTEM', 'TIMELINESS', '统计时间字段晚于当前时间的记录数。', '[]', 'COLUMN', 'select count(*) as future_count from ${Schema_Table} where ${Column} > current_timestamp', 1),
(2047489216606134305, 'default', null, 0, '2026-04-24 09:34:04', '2026-04-24 09:34:04', 2047489207831650305, '字段间取值不一致数统计', 'DQ_FIELD_EQUALITY_INCONSISTENT_COUNT', 'SYSTEM', 'CONSISTENCY', '统计当前字段与同表对比字段取值不一致的记录数，包含单侧为空场景。', '[]', 'COLUMN', 'select count(*) as inconsistent_count from ${Schema_Table} where (${Column} <> ${CompareColumn}) or (${Column} is null and ${CompareColumn} is not null) or (${Column} is not null and ${CompareColumn} is null)', 1),
(2047489216606134310, 'default', null, 0, '2026-04-24 09:34:04', '2026-04-24 09:34:04', 2047489207831650305, '字段间顺序异常数统计', 'DQ_FIELD_ORDER_INVALID_COUNT', 'SYSTEM', 'CONSISTENCY', '统计当前字段大于同表对比字段的记录数，适用于开始时间不应晚于结束时间等场景。', '[]', 'COLUMN', 'select count(*) as invalid_count from ${Schema_Table} where ${Column} is not null and ${CompareColumn} is not null and ${Column} > ${CompareColumn}', 1),
(2047489216606134315, 'default', null, 0, '2026-04-24 09:34:04', '2026-04-24 09:34:04', 2047489207831650305, '负数值数量统计', 'DQ_NEGATIVE_VALUE_COUNT', 'SYSTEM', 'ACCURACY', '统计小于 0 的数值记录数，适用于金额、数量等非负字段校验。', '[]', 'COLUMN', 'select count(*) as negative_count from ${Schema_Table} where ${Column} < 0', 1),
(2047489216606134319, 'default', null, 0, '2026-04-24 09:34:04', '2026-04-24 09:34:04', 2047489207831650305, '零值或空值数量统计', 'DQ_ZERO_OR_NULL_VALUE_COUNT', 'SYSTEM', 'ACCURACY', '统计字段为空或等于 0 的记录数，适用于不应为空且不应为零的指标字段。', '[]', 'COLUMN', 'select count(*) as zero_or_null_count from ${Schema_Table} where ${Column} is null or ${Column} = 0', 1);
